Item.method_code:
const { itemTypeName, itemType, itemId, commandFactory } = options

const itemNode = aras.getItemLastVersion(
	itemTypeName,
	itemId
);

const commandOptions = {
	itemTypeName,
	itemType,
	itemNode
}

const commandAlias = target['command_alias@keyed_name'];
const openItemCommand = await commandFactory(commandAlias, commandOptions);

return openItemCommand.execute();
